package com.shopstream.inventory;

/** Thrown when an order can never be processed, however often we retry (bad SKU, quantity 0). */
public class InvalidOrderException extends RuntimeException {

    public InvalidOrderException(String message) {
        super(message);
    }
}

package com.shopstream.inventory;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.listener.CommonErrorHandler;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;

@Configuration
public class ErrorHandlingConfig {

    @Bean
    public CommonErrorHandler orderErrorHandler(KafkaTemplate<String, Object> template) {
        // Where exhausted records go: <original topic>-dlt, same partition number
        var recoverer = new DeadLetterPublishingRecoverer(template);

        // When to try again: 1 s, 2 s, 4 s, 8 s, 10 s, 10 s (6 retries, 7 deliveries)
        var backOff = new ExponentialBackOffWithMaxRetries(6);
        backOff.setInitialInterval(1_000L);
        backOff.setMultiplier(2.0);
        backOff.setMaxInterval(10_000L);

        var handler = new DefaultErrorHandler(recoverer, backOff);
        // Retrying a validation failure cannot help: go to the DLT on the first failure
        handler.addNotRetryableExceptions(InvalidOrderException.class);
        return handler;
    }
}

