package com.shopstream.inventory;

import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.common.header.Header;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.KafkaHeaders;
import org.springframework.stereotype.Component;

@Component
public class OrderDeadLetterListener {

    private static final Logger log = LoggerFactory.getLogger(OrderDeadLetterListener.class);

    // Read the DLT as plain strings: a malformed payload must not fail here as well
    @KafkaListener(
            topics = "orders-dlt",
            groupId = "inventory-service-dlt",
            properties = {
                "key.deserializer=org.apache.kafka.common.serialization.StringDeserializer",
                "value.deserializer=org.apache.kafka.common.serialization.StringDeserializer"
            })
    public void onDeadLetter(ConsumerRecord<String, String> record) {
        log.error("Dead letter: key={} cause={} message={} value={}",
                record.key(),
                header(record, KafkaHeaders.DLT_EXCEPTION_FQCN),
                header(record, KafkaHeaders.DLT_EXCEPTION_MESSAGE),
                record.value());
    }

    private static String header(ConsumerRecord<?, ?> record, String name) {
        Header h = record.headers().lastHeader(name);
        return h == null ? "n/a" : new String(h.value(), StandardCharsets.UTF_8);
    }
}

package com.shopstream.inventory;

import com.shopstream.events.OrderCreated;
import java.util.Map;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.serialization.ByteArraySerializer;
import org.apache.kafka.common.serialization.StringSerializer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.DefaultKafkaProducerFactory;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.serializer.DelegatingByTypeSerializer;
import org.springframework.kafka.support.serializer.JacksonJsonSerializer;

@Configuration
public class DeadLetterTemplateConfig {

    @Bean
    public KafkaTemplate<String, Object> kafkaTemplate(
            @Value("${spring.kafka.bootstrap-servers}") String bootstrapServers) {
        // raw bytes (from a failed deserialization) are written as they are,
        // OrderCreated objects are written as JSON
        var valueSerializer = new DelegatingByTypeSerializer(Map.of(
                byte[].class, new ByteArraySerializer(),
                OrderCreated.class, new JacksonJsonSerializer<Object>()));
        var producerFactory = new DefaultKafkaProducerFactory<String, Object>(
                Map.of(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers),
                new StringSerializer(), valueSerializer);
        return new KafkaTemplate<>(producerFactory);
    }
}

package com.shopstream.search;

import com.shopstream.events.OrderCreated;
import java.util.List;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.listener.BatchListenerFailedException;
import org.springframework.stereotype.Component;

@Component
public class OrderBatchListener {

    private final SearchIndex index;

    public OrderBatchListener(SearchIndex index) {
        this.index = index;
    }

    @KafkaListener(topics = "orders", groupId = "search-indexer", batch = "true")
    public void onOrders(List<ConsumerRecord<String, OrderCreated>> records) {
        for (ConsumerRecord<String, OrderCreated> record : records) {
            if (record.value() == null) {
                // ErrorHandlingDeserializer hands over a failed record with a null value
                throw new BatchListenerFailedException("Deserialization failed", record);
            }
            try {
                index.upsert(record.value());
            }
            catch (Exception e) {
                // tells the container which record failed
                throw new BatchListenerFailedException("Indexing failed", e, record);
            }
        }
    }
}

package com.shopstream.inventory;

import com.shopstream.events.OrderCreated;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.BackOff;
import org.springframework.kafka.annotation.DltHandler;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.annotation.RetryableTopic;
import org.springframework.stereotype.Component;

@Component
public class OrderRetryListener {

    private static final Logger log = LoggerFactory.getLogger(OrderRetryListener.class);

    private final InventoryService inventory;

    public OrderRetryListener(InventoryService inventory) {
        this.inventory = inventory;
    }

    @RetryableTopic(
            kafkaTemplate = "kafkaTemplate",
            attempts = "4",
            backOff = @BackOff(delay = 1000, multiplier = 2.0, maxDelay = 16000),
            exclude = InvalidOrderException.class,
            numPartitions = "3")
    @KafkaListener(topics = "orders", groupId = "inventory-service")
    public void onOrderCreated(OrderCreated event) {
        inventory.reserve(event);
    }

    @DltHandler
    public void onDeadLetter(ConsumerRecord<String, OrderCreated> record) {
        log.error("Order {} failed all retries (dead letter {}-{}@{})",
                record.key(), record.topic(), record.partition(), record.offset());
    }
}

package com.shopstream.inventory;

import java.util.List;
import org.springframework.context.annotation.Configuration;
import org.springframework.dao.TransientDataAccessException;
import org.springframework.kafka.annotation.EnableKafka;
import org.springframework.kafka.retrytopic.RetryTopicConfigurationSupport;
import org.springframework.util.backoff.FixedBackOff;

@EnableKafka
@Configuration
public class RetryConfig extends RetryTopicConfigurationSupport {

    @Override
    protected void configureBlockingRetries(BlockingRetriesConfigurer blockingRetries) {
        blockingRetries
                .retryOn(TransientDataAccessException.class)
                .backOff(new FixedBackOff(200L, 2L));
    }

    @Override
    protected void manageNonBlockingFatalExceptions(
            List<Class<? extends Throwable>> nonBlockingFatalExceptions) {
        nonBlockingFatalExceptions.add(InvalidOrderException.class);
    }
}

package com.shopstream.inventory;

import java.util.List;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.retrytopic.RetryTopicConfiguration;
import org.springframework.kafka.retrytopic.RetryTopicConfigurationBuilder;

@Configuration
public class OrdersRetryConfiguration {
    @Bean
    public RetryTopicConfiguration ordersRetry(KafkaTemplate<String, Object> template) {
        return RetryTopicConfigurationBuilder
                .newInstance()
                .exponentialBackoff(1_000, 2, 16_000)
                .maxAttempts(4)
                .autoCreateTopicsWith(3, (short) 1)
                .includeTopics(List.of("orders"))
                .notRetryOn(InvalidOrderException.class)
                .create(template);
    }
}

