package com.shopstream.inventory;

import com.shopstream.events.OrderCreated;
import com.shopstream.events.OrderLine;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InventoryService {

    private static final Logger log = LoggerFactory.getLogger(InventoryService.class);
    private static final String CONSUMER = "inventory-reserve";

    private final JdbcClient jdbc;

    public InventoryService(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Transactional
    public void reserve(OrderCreated event) {
        int inserted = jdbc.sql("""
                INSERT INTO processed_event (consumer, event_id)
                VALUES (:consumer, :eventId)
                ON CONFLICT (consumer, event_id) DO NOTHING
                """)
                .param("consumer", CONSUMER)
                .param("eventId", event.eventId())
                .update();
        if (inserted == 0) {
            log.info("Event {} already processed, skipping", event.eventId());
            return;
        }
        for (OrderLine line : event.lines()) {
            int updated = jdbc.sql("""
                    UPDATE stock SET reserved = reserved + :qty
                    WHERE sku = :sku AND on_hand - reserved >= :qty
                    """)
                    .param("qty", line.qty())
                    .param("sku", line.sku())
                    .update();
            if (updated == 0) {
                // rolls back the transaction, including the processed_event row
                throw new InvalidOrderException("Unknown SKU or not enough stock: " + line.sku());
            }
        }
    }
}

package com.shopstream.inventory;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
public class ProcessedEventCleanup {

    private static final Logger log = LoggerFactory.getLogger(ProcessedEventCleanup.class);

    private final JdbcClient jdbc;

    public ProcessedEventCleanup(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    // needs @EnableScheduling on a configuration class
    @Scheduled(cron = "0 15 3 * * *")
    @Transactional
    public void purge() {
        int deleted = jdbc
                .sql("DELETE FROM processed_event WHERE processed_at < now() - interval '14 days'")
                .update();
        log.info("Purged {} processed_event rows older than 14 days", deleted);
    }
}
